const upsertOpenDVRChapter = `-- name: UpsertOpenDVRChapter :exec
INSERT INTO foghorn.dvr_chapters (
  chapter_id, artifact_hash, mode, interval_seconds, start_ms, end_ms,
  is_current, state, segment_count, has_gaps, created_at
) VALUES (
  $1, $2, $3, $4,
  $5, $6, true, $7, 0, false, NOW()
)
ON CONFLICT (chapter_id) DO UPDATE SET is_current = EXCLUDED.is_current
`

type UpsertOpenDVRChapterParams struct {
	ChapterID       string        `db:"chapter_id" json:"chapter_id"`
	ArtifactHash    string        `db:"artifact_hash" json:"artifact_hash"`
	Mode            string        `db:"mode" json:"mode"`
	IntervalSeconds sql.NullInt32 `db:"interval_seconds" json:"interval_seconds"`
	StartMs         int64         `db:"start_ms" json:"start_ms"`
	EndMs           int64         `db:"end_ms" json:"end_ms"`
	State           string        `db:"state" json:"state"`
}

func (q *Queries) UpsertOpenDVRChapter(ctx context.Context, arg UpsertOpenDVRChapterParams) error {
	_, err := q.db.ExecContext(ctx, upsertOpenDVRChapter,
		arg.ChapterID,
		arg.ArtifactHash,
		arg.Mode,
		arg.IntervalSeconds,
		arg.StartMs,
		arg.EndMs,
		arg.State,
	)
	return err
}
